#include "../minimap2-cuda/device/device_kernel.cu"
#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <stdexcept>
#include <cstring>
#include <cstdio>
#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA%s:%d\n",cudaGetErrorString(e),__LINE__);exit(2);}}while(0)
using B=unsigned char;
std::vector<B>read(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error(p);size_t n=f.tellg();f.seekg(0);std::vector<B>x(n);f.read((char*)x.data(),n);if(!f)throw std::runtime_error("short");return x;}
struct Buf{B*b;size_t n;Buf(size_t m,const B*data=nullptr,int value=0):n(m){C(cudaMalloc(&b,n+128));C(cudaMemset(b,165,n+128));if(data)C(cudaMemcpy(b+64,data,n,cudaMemcpyHostToDevice));else C(cudaMemset(b+64,value,n));}~Buf(){C(cudaFree(b));}template<class T>T*ptr(){return(T*)(b+64);}std::vector<B>all(){std::vector<B>x(n+128);C(cudaMemcpy(x.data(),b,n+128,cudaMemcpyDeviceToHost));return x;}};
std::vector<B>guarded(const std::vector<B>&x){std::vector<B>r(x.size()+128,165);std::copy(x.begin(),x.end(),r.begin()+64);return r;}
void append(std::vector<B>&a,const std::vector<B>&b){a.insert(a.end(),b.begin(),b.end());}
int main(){auto a=read("anchors_u16.bin"),c=read("control_u8.bin"),ro=read("oracle_return_i32.bin"),mo=read("oracle_max_i32.bin"),po=read("oracle_parent_i32.bin");size_t batches=c.size()/8/PE_NUM;std::vector<B>pre,expected;append(pre,guarded(a));append(pre,guarded(c));append(expected,guarded(ro));append(expected,guarded(mo));append(expected,guarded(po));for(int trial=0;trial<=5;trial++){Buf A(a.size(),a.data()),CT(c.size(),c.data()),R(ro.size()),M(mo.size()),P(po.size(),nullptr,255);auto apre=A.all(),cpre=CT.all();std::vector<B>actualpre;append(actualpre,apre);append(actualpre,cpre);C(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(size_t batch=0;batch<batches;batch++)device_chain_tiled<<<BLOCK_NUM,64>>>(R.ptr<return_dt>()+batch*PE_NUM*TILE_SIZE,A.ptr<anchor_dt>()+batch*PE_NUM*TILE_SIZE_ACTUAL,CT.ptr<control_dt>()+batch*PE_NUM,M.ptr<int>(),P.ptr<int>(),5000,5000,500);C(cudaGetLastError());C(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();std::vector<B>actual;append(actual,R.all());append(actual,M.all());append(actual,P.all());bool ok=actualpre==pre&&actual==expected&&A.all()==apre&&CT.all()==cpre;if(!ok){size_t i=0;while(i<actual.size()&&actual[i]==expected[i])i++;fprintf(stderr,"fullcheck failed prefix%d outoffset%zu actual%d expected%d\n",int(actualpre==pre),i,i<actual.size()?actual[i]:-1,i<expected.size()?expected[i]:-1);return 3;}if(trial){std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/minimap2_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)actualpre.data(),actualpre.size());f.write((char*)actual.data(),actual.size());f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"jit_excluded\":true,\"timing_region\":\"all_source_batched64lane_circular_DP_kernel_launches_and_wholedevice_completion_excludes_scheduler_allocation_capture\",\"iterations\":%zu,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,actualpre.size()+actual.size(),batches,path.c_str(),actualpre.size()+actual.size());fflush(stdout);}}}
